def moths():
    """وفرة أنواع العث في أربع مناطق: دوائر ملونة مرقمة بالنوع"""
    cols = {1: '#e0801b', 2: '#2e7d32', 3: '#1e7fc4', 4: '#c2185b'}
    pan = [('الموقع (أ)', [1, 1, 2, 3, 3, 3]), ('الموقع (ب)', [1, 1, 1, 1]), ('الموقع (ج)', [1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4]), ('الموقع (د)', [1, 2, 3] + [4] * 9)]
    s = '<svg viewBox="0 0 720 300" width="100%" font-family="Tajawal,Cairo,sans-serif" text-anchor="middle"><defs>'
    for k, c in cols.items(): s += f'<radialGradient id="mo{k}" cx="35%" cy="30%"><stop offset="0" stop-color="{lighten(c,.55)}"/><stop offset="1" stop-color="{c}"/></radialGradient>'
    s += '<filter id="mos"><feDropShadow dx="1" dy="2" stdDeviation="1.6" flood-opacity=".35"/></filter></defs>'
    for i, (t, items) in enumerate(pan):
        x0 = 15 + (i % 2) * 355; y0 = 10 + (i // 2) * 150
        s += f'<rect x="{x0}" y="{y0}" width="340" height="138" rx="14" fill="#f4f7fb" stroke="#c9d3e3"/><text x="{x0+170}" y="{y0+22}" font-size="16" font-weight="800" fill="#1d2433">{t}</text>'
        for j, k in enumerate(items):
            cx = x0 + 30 + (j % 12) * 25.5; cy = y0 + 55 + (j // 12) * 32 if len(items) > 12 else y0 + 60 + (j // 6) * 34
            if len(items) <= 12: cx = x0 + 45 + (j % 6) * 50; cy = y0 + 55 + (j // 6) * 40
            s += f'<circle cx="{cx}" cy="{cy}" r="14" fill="url(#mo{k})" filter="url(#mos)"/><text x="{cx}" y="{cy+5}" font-size="14" font-weight="800" fill="#fff">{k}</text>'
    return s + '</svg>'
